// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(c));
        vm.prank(actor);
        try c.airDrop() {
            // call succeeded
        } catch {
            // call reverted
        }
        // Rule: no caller lacking the valid supportsToken response may ever
        // hold tokens; for any fuzzed actor the reference never grants tokens.
        assertTrue(c.tokenBalance(actor) == 0, "tokens granted to invalid caller");
    }
}
